,p_static_id=>'load-employee-details'
,p_display_sequence=>20
,p_activity_type=>'NATIVE_PLSQL'
,p_activity_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT e.first_name || '' '' || e.last_name,',
'           e.email,',
'           e.hire_date,',
'           d.name,',
'           mgr.email',
'      INTO :V_EMPLOYEE_NAME,',
'           :V_EMPLOYEE_EMAIL,',
'           :V_START_DATE,',
'           :V_DEPARTMENT,',
'           :V_DEPARTMENT_MANAGER',
'      FROM tms_employees e',
'      LEFT JOIN tms_departments d ON d.dept_id = e.dept_id',
'      LEFT JOIN tms_employees mgr ON mgr.employee_id = d.manager_id',
'     WHERE e.employee_id = :V_EMPLOYEE_ID;',
'END;'))
,p_activity_code_language=>'PLSQL'
,p_location=>'LOCAL'
,p_diagram=>'{"position":{"x":800,"y":970}}'
