prompt --application/shared_components/automations/monthly_leave_accrual
begin
wwv_flow_imp_shared.create_automation(
 p_id=>wwv_flow_imp.id(5645632759029504111)
,p_name=>'Monthly Leave Accrual'
,p_static_id=>'monthly-leave-accrual'
,p_trigger_type=>'POLLING'
,p_polling_interval=>'FREQ=MONTHLY;BYMONTHDAY=1;BYHOUR=0;BYMINUTE=0;BYSECOND=0'
,p_polling_status=>'DISABLED'
,p_result_type=>'ROWS'
,p_location=>'LOCAL'
,p_query_type=>'SQL'
,p_query_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT employee_id',
'  FROM tms_employees',
' WHERE status = ''Active'''))
,p_commit_each_row=>false
,p_error_handling_type=>'ABORT'
);
wwv_flow_imp_shared.create_automation_action(
 p_id=>wwv_flow_imp.id(5645497166021837902)
,p_automation_id=>wwv_flow_imp.id(5645632759029504111)
,p_name=>'Merge Leave Balances'
,p_static_id=>'merge-leave-balances'
,p_execution_sequence=>10
,p_action_type=>'NATIVE_PLSQL'
,p_action_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'l_accrual NUMBER := ROUND(apex_app_setting.get_value(''MAX_LEAVE_DAYS'') / 12, 1);',
'BEGIN',
'    MERGE INTO tms_leave_balances b',
'    USING (',
'        SELECT :EMPLOYEE_ID AS employee_id,',
'            1 AS leave_type_id,',
'            EXTRACT(YEAR FROM SYSDATE) AS leave_year',
'        FROM dual',
'    ) s',
'    ON (b.employee_id = s.employee_id',
'    AND b.leave_type_id = s.leave_type_id',
'    AND b.year = s.leave_year)',
'    WHEN MATCHED THEN',
'        UPDATE SET accrued = NVL(b.accrued, 0) + l_accrual,',
'                remaining = NVL(b.remaining, 0) + l_accrual',
'    WHEN NOT MATCHED THEN',
'        INSERT (employee_id, leave_type_id, year, accrued, remaining)',
'        VALUES (s.employee_id, s.leave_type_id, s.leave_year, l_accrual, l_accrual);',
'END;'))
,p_action_clob_language=>'PLSQL'
,p_location=>'LOCAL'
,p_stop_execution_on_error=>true
);
end;
/
prompt --application/shared_components/automations/probation_end_alert
begin
wwv_flow_imp_shared.create_automation(
 p_id=>wwv_flow_imp.id(5645520796724845660)
,p_name=>'Probation End Alert'
,p_static_id=>'probation-end-alert'
,p_trigger_type=>'POLLING'
,p_polling_interval=>'FREQ=DAILY;INTERVAL=1;BYHOUR=7;BYMINUTE=0'
,p_polling_status=>'DISABLED'
,p_result_type=>'ROWS'
,p_location=>'LOCAL'
,p_query_type=>'SQL'
,p_query_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT e.employee_id,',
'       e.first_name || '' '' || e.last_name AS employee_name,',
'       e.hire_date,',
'       ADD_MONTHS(e.hire_date,',
'           apex_app_setting.get_value(''PROBATION_MONTHS'')) AS probation_end',
'  FROM tms_employees e',
' WHERE e.status = ''Active''',
'   AND ADD_MONTHS(e.hire_date,',
'       apex_app_setting.get_value(''PROBATION_MONTHS''))',
'       BETWEEN TRUNC(SYSDATE) AND TRUNC(SYSDATE) + 7'))
,p_commit_each_row=>false
,p_error_handling_type=>'ABORT'
);
wwv_flow_imp_shared.create_automation_action(
 p_id=>wwv_flow_imp.id(5645521186398845669)
,p_automation_id=>wwv_flow_imp.id(5645520796724845660)
,p_name=>'Send Probation Alert'
,p_static_id=>'new-action'
,p_execution_sequence=>10
,p_action_type=>'NATIVE_SEND_EMAIL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'email_template_id', wwv_flow_imp.id(5645000292646440420),
  'from', '&APP_EMAIL.',
  'placeholder_values', wwv_flow_string.join(wwv_flow_t_varchar2(
    '{',
    '    "EMPLOYEE_NAME":"&EMPLOYEE_NAME.",',
    '    "HIRE_DATE":"&HIRE_DATE.",',
    '    "PROBATION_END":"&PROBATION_END."',
    '}')),
  'send_immediately', 'N',
  'to', 'apex_app_setting.get_value(''SUPPORT_EMAIL'')')).to_clob
,p_stop_execution_on_error=>true
);
end;
