prompt --application/shared_components/automations/task_overdue
begin
wwv_flow_imp_shared.create_automation(
 p_id=>wwv_flow_imp.id(5645043305673462413)
,p_name=>'Task Overdue'
,p_static_id=>'task-overdue'
,p_trigger_type=>'POLLING'
,p_polling_interval=>'FREQ=DAILY;INTERVAL=1;BYHOUR=8;BYMINUTE=0'
,p_polling_status=>'DISABLED'
,p_result_type=>'ROWS'
,p_location=>'LOCAL'
,p_query_type=>'SQL'
,p_query_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT t.task_id,',
'       t.task_name,',
'       t.due_date,',
'       TO_CHAR(t.due_date, ''DD-Mon-YYYY'') AS due_date_text,',
'       e.employee_id,',
'       e.email AS employee_email,',
'       e.first_name || '' '' || e.last_name AS employee_name',
'  FROM tms_onboarding_tasks t',
'  JOIN tms_employees e ON e.employee_id = t.employee_id',
' WHERE t.due_date < TRUNC(SYSDATE)',
'   AND t.status NOT IN (''Completed'', ''Cancelled'', ''Overdue'')'))
,p_commit_each_row=>false
,p_error_handling_type=>'ABORT'
);
wwv_flow_imp_shared.create_automation_action(
