 p_id=>wwv_flow_imp.id(5512693307486400961)
,p_label=>'Ess My Tasks Search'
,p_static_id=>'ess-my-tasks-search'
,p_search_type=>'SIMPLE'
,p_location=>'LOCAL'
,p_query_type=>'SQL'
,p_query_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    t.task_id,',
'    t.task_name,',
'    t.status,',
'    t.due_date,',
'    t.task_name AS result_title,',
'    ''Status: '' || t.status ||',
'        CASE',
'            WHEN t.due_date IS NOT NULL',
'                THEN '' - Due: '' || TO_CHAR(t.due_date, ''DD-MON-YYYY'')',
'        END AS result_description',
'FROM tms_onboarding_tasks t',
'JOIN tms_employees e',
'    ON e.employee_id = t.employee_id',
'WHERE UPPER(e.email) = UPPER(:APP_USER)'))
,p_searchable_columns=>'TASK_NAME:STATUS:RESULT_TITLE:RESULT_DESCRIPTION'
,p_pk_column_name=>'TASK_ID'
,p_title_column_name=>'RESULT_TITLE'
,p_description_column_name=>'RESULT_DESCRIPTION'
,p_link_target_type=>'REDIRECT_PAGE'
,p_link_target=>'f?p=&APP_ID.:2:&SESSION.::&DEBUG.'
,p_icon_source_type=>'INITIALS'
);
end;
