wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(5522485930480420159)
,p_plug_name=>'Onboarding Progress'
,p_static_id=>'onboarding-progress'
,p_parent_plug_id=>wwv_flow_imp.id(4595405186279265791)
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    COUNT(*) AS total_count,',
'    NVL(',
'        SUM(',
'            CASE',
'                WHEN t.status = ''Completed'' THEN 1',
'                ELSE 0',
'            END',
'        ),',
'        0',
'    ) AS done_count,',
'    CASE',
'        WHEN COUNT(*) = 0 THEN 0',
'        ELSE ROUND(',
'            SUM(',
'                CASE',
'                    WHEN t.status = ''Completed'' THEN 1',
'                    ELSE 0',
'                END',
'            ) * 100 / COUNT(*)',
'        )',
'    END AS completion_pct',
'FROM tms_onboarding_tasks t',
'JOIN tms_employees e',
'  ON e.employee_id = t.employee_id',
'WHERE UPPER(e.email) = UPPER(:APP_USER)'))
,p_template_component_type=>'PARTIAL'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$ONBOARDING_PROGRESS_BAR'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'COMPLETION_PCT', '&COMPLETION_PCT.',
  'DONE_COUNT', '&DONE_COUNT.',
  'TOTAL_COUNT', '&TOTAL_COUNT.')).to_clob
);
