wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(4633939297223642248)
,p_plug_name=>'My Leave History'
,p_static_id=>'my-leave-history'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2103954283454391425
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT leave_type_id,',
'       start_date,',
'       end_date,',
'       days_requested,',
'       status',
'FROM   tms_leave_requests lr',
'WHERE  employee_id = :P5_EMPLOYEE_ID',
'       AND ( employee_id = :APP_EMPLOYEE_ID',
'              OR EXISTS (SELECT 1',
'                         FROM   tms_roles r',
'                                JOIN tms_employee_roles er',
'                                  ON er.role_id = r.role_id',
'                         WHERE  r.role_code = ''HR_ADMIN''',
'                                AND er.employee_id = :APP_EMPLOYEE_ID) )',
'ORDER  BY start_date DESC'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P5_EMPLOYEE_ID'
