wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(6081327720347620651)
,p_plug_name=>'Organisation Structure'
,p_static_id=>'organisation-structure'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4075786578761660127
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    e.employee_id AS id,',
'    e.manager_id AS parent_id,',
'    e.first_name || '' '' || e.last_name AS title,',
'    j.title || '' - '' || d.name AS tooltip',
'FROM tms_employees e',
'LEFT JOIN tms_jobs j',
'    ON j.job_id = e.job_id',
'LEFT JOIN tms_departments d',
'    ON d.dept_id = e.dept_id',
'WHERE e.status = ''Active''',
'START WITH e.manager_id IS NULL',
'CONNECT BY PRIOR e.employee_id = e.manager_id',
'ORDER SIBLINGS BY e.first_name, e.last_name',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_JSTREE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'activate_node_link_with', 'S',
  'default_icon_css_class', 'icon-tree-folder',
