 p_id=>wwv_flow_imp.id(5522488729363420187)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Upload Docs'
,p_static_id=>'upload-docs'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_blob BLOB;',
'BEGIN',
'    IF :P10_PASSPORT IS NOT NULL THEN',
'        SELECT blob_content',
'        INTO   v_blob',
'        FROM   apex_application_temp_files',
'        WHERE  name = :P10_PASSPORT;',
'',
'        APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE(',
'            p_collection_name => ''ONBOARDING_COLLECTION'',',
'            p_seq             => 1,',
'            p_blob_number     => 1,',
'            p_blob_value      => v_blob',
'        );',
'    END IF;',
'',
'    IF :P10_CONTRACT_BLOB IS NOT NULL THEN',
'        SELECT blob_content',
'        INTO   v_blob',
'        FROM   apex_application_temp_files',
'        WHERE  name = :P10_CONTRACT_BLOB;',
'',
'        APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE(',
'            p_collection_name => ''ONBOARDING_COLLECTION'',',
'            p_seq             => 2,',
'            p_blob_number     => 1,',
'            p_blob_value      => v_blob',
'        );',
'    END IF;',
'',
'    IF :P10_TAX_FORM_BLOB IS NOT NULL THEN',
'        SELECT blob_content',
'        INTO   v_blob',
'        FROM   apex_application_temp_files',
'        WHERE  name = :P10_TAX_FORM_BLOB;',
'',
'        APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE(',
'            p_collection_name => ''ONBOARDING_COLLECTION'',',
'            p_seq             => 3,',
'            p_blob_number     => 1,',
'            p_blob_value      => v_blob',
'        );',
